  "首页副标题语言": { en: "Home subtitle language", ja: "ホームのサブタイトル言語" }, "跟随界面": { en: "Follow interface", ja: "表示言語に合わせる" }, "副标题效果": { en: "Subtitle effect", ja: "サブタイトル効果" }, "逐字打字": { en: "Typewriter", ja: "タイプライター" }, "柔和淡入": { en: "Soft fade", ja: "フェードイン" }, "轻盈上浮": { en: "Gentle rise", ja: "ふんわり浮上" }, "静态文字": { en: "Static text", ja: "静的テキスト" }, "淡入和上浮每 5 秒换一句；暂停界面动画时显示静态文字。": { en: "Fade and rise rotate phrases every 5 seconds. Pausing motion shows static text.", ja: "フェードと浮上は5秒ごとに文を切り替えます。アニメーション停止中は固定表示です。" }, "入站欢迎动画": { en: "Welcome animation", ja: "ウェルカムアニメーション" }, "开启后每次浏览器会话显示一次；关闭后直接进入页面，也可在欢迎画面右上角跳过。": { en: "When enabled, it appears once per browser session. Disable it to skip, or use Skip in its top-right corner.", ja: "有効にするとブラウザーセッションごとに一度表示します。無効にすると省略でき、右上のボタンからもスキップできます。" },
  "预设名称": { en: "Preset name", ja: "プリセット名" }, "给这套设置起个名字": { en: "Name this preset", ja: "プリセットに名前を付ける" }, "保存为我的预设": { en: "Save as my preset", ja: "マイプリセットに保存" }, "保存当前配色、字体、封面、背景、动效和页面跳转设置，随时切回来。预设保存在此浏览器，恢复默认不会删除。": { en: "Save the current colors, fonts, cover, background, effects, and navigation. Presets stay in this browser and survive reset.", ja: "配色・フォント・カバー・背景・効果・移動設定を保存します。プリセットはこのブラウザーに保存され、初期化後も残ります。" }, "先为这套设置取个名字。": { en: "Give this preset a name first.", ja: "まずプリセットに名前を付けてください。" }, "这个名字已有预设，请换个名字，或使用下方的更新按钮。": { en: "That name is already used. Choose another name or update the preset below.", ja: "同じ名前のプリセットがあります。別の名前にするか、下の更新ボタンを使ってください。" }, "最多保存20套预设，请先删除不再使用的预设。": { en: "You can save up to 20 presets. Delete one before adding another.", ja: "プリセットは最大20件です。不要なものを削除してください。" }, "还没有预设。调好喜欢的外观后，保存第一套吧。": { en: "No presets yet. Save your first one after customizing the appearance.", ja: "プリセットはありません。外観を調整して最初のプリセットを保存しましょう。" }, "应用": { en: "Apply", ja: "適用" },
  "已保存「{name}」。": { en: "Saved “{name}”.", ja: "「{name}」を保存しました。" }, "已应用「{name}」。": { en: "Applied “{name}”.", ja: "「{name}」を適用しました。" }, "已应用预设，但浏览器未允许保存部分设置。": { en: "Preset applied, but the browser blocked saving some settings.", ja: "プリセットを適用しましたが、一部の設定を保存できませんでした。" }, "已用当前设置更新「{name}」。": { en: "Updated “{name}” with the current settings.", ja: "現在の設定で「{name}」を更新しました。" }, "已删除「{name}」，当前外观保持不变。": { en: "Deleted “{name}”. The current appearance is unchanged.", ja: "「{name}」を削除しました。現在の外観はそのままです。" }, "用当前设置更新": { en: "Update with current settings", ja: "現在の設定で更新" }, "删除预设": { en: "Delete preset", ja: "プリセットを削除" }, "删除": { en: "Delete", ja: "削除" },
