export function translate(text: string, language: UiLanguage, values?: Record<string, string | number>): string {
  const translated = language === "zh" ? text : translations[text]?.[language] ?? text;
  return values ? translated.replace(/\{(\w+)\}/g, (_, key: string) => String(values[key] ?? `{${key}}`)) : translated;
}

export function useTranslation() {
  const { preferences } = useAppearance();
  const language = ((preferences as typeof preferences & { language?: UiLanguage }).language ?? "zh") as UiLanguage;
  const tx = useCallback((text: string, values?: Record<string, string | number>) => translate(text, language, values), [language]);
  return { language, tx };
}

